import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  LinearProgress,
  List,
  ListItem,
  ListItemText,
  Stack,
  Typography,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import ApiService from '../../services/api';

interface IsoGapChecklist {
  overallReadinessScore?: number;
  priorityActions?: Array<{ title?: string; description?: string; priority?: string }>;
  openGaps?: Array<{ title?: string; description?: string }>;
}

export const DashboardIsoReadinessCard: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [checklist, setChecklist] = useState<IsoGapChecklist | null>(null);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await ApiService.getIsoGapClosureChecklist({
          period: 'annual',
          framework: 'all',
        });
        if (cancelled) return;
        if (response?.success === false) {
          setChecklist(null);
          setError(response?.message || 'Unable to load ISO readiness');
          return;
        }
        setChecklist((response?.data?.checklist as IsoGapChecklist) || null);
      } catch (err: unknown) {
        if (!cancelled) {
          setChecklist(null);
          setError(err instanceof Error ? err.message : 'Unable to load ISO readiness');
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, []);

  if (loading) {
    return (
      <Card variant="outlined" sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
            ISO readiness
          </Typography>
          <LinearProgress />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card variant="outlined" sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
            ISO readiness
          </Typography>
          <Alert severity="error">{error}</Alert>
        </CardContent>
      </Card>
    );
  }

  if (!checklist) {
    return null;
  }

  const score = Math.round(Number(checklist.overallReadinessScore) || 0);
  const actions = (checklist.priorityActions || []).slice(0, 3);
  const openGaps = checklist.openGaps?.length ?? 0;

  if (score >= 85 && openGaps === 0) {
    return null;
  }

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Stack
          direction={{ xs: 'column', sm: 'row' }}
          justifyContent="space-between"
          alignItems={{ xs: 'flex-start', sm: 'center' }}
          spacing={2}
          sx={{ mb: 2 }}
        >
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              ISO readiness
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Gap-closure score for ISO 14064 / 14067 reporting
            </Typography>
          </Box>
          <Typography variant="h5" sx={{ fontWeight: 800, color: 'primary.main' }}>
            {score}%
          </Typography>
        </Stack>

        <LinearProgress
          variant="determinate"
          value={Math.min(100, Math.max(0, score))}
          sx={{ height: 8, borderRadius: 1, mb: 2 }}
        />

        {openGaps > 0 && (
          <Alert severity="warning" sx={{ mb: 2 }}>
            {openGaps} open gap{openGaps === 1 ? '' : 's'} in your inventory and factor registry.
          </Alert>
        )}

        {actions.length > 0 && (
          <List dense disablePadding sx={{ mb: 2 }}>
            {actions.map((action, index) => (
              <ListItem key={`${action.title || 'action'}-${index}`} disablePadding sx={{ py: 0.25 }}>
                <ListItemText
                  primary={action.title || 'Priority action'}
                  secondary={action.description}
                  primaryTypographyProps={{ variant: 'body2', fontWeight: 600 }}
                  secondaryTypographyProps={{ variant: 'caption' }}
                />
              </ListItem>
            ))}
          </List>
        )}

        <Button size="small" variant="outlined" onClick={() => navigate('/reporting')}>
          View reporting &amp; ISO checklists
        </Button>
      </CardContent>
    </Card>
  );
};

export default DashboardIsoReadinessCard;
